        Operation* const src = ctx.create_operation(ctx.intern_op("smoke", "src"), {}, 1U, ctx.type_i32());
        Operation* const op = tensor::build_reduce(ctx, src->result(0U), ctx.attr_int(0), ctx.attr_string("x"), ctx.type_i32());
        CHECK(op != nullptr);
        CHECK(ctx.verify(*op));
